CREATE TABLE rm_intercompany_dispositions (
  disposition_id TEXT PRIMARY KEY CHECK(length(disposition_id) BETWEEN 3 AND 80),
  canonical_payload TEXT NOT NULL,
  payload_hash TEXT NOT NULL CHECK(length(payload_hash)=64),
  created_at TEXT NOT NULL
);
CREATE TABLE rm_intercompany_disposition_events (
  id INTEGER PRIMARY KEY,
  disposition_id TEXT NOT NULL REFERENCES rm_intercompany_dispositions(disposition_id),
  event_type TEXT NOT NULL CHECK(event_type IN ('proposed','approved','rejected','cancelled','settled','superseded','exception')),
  payload_hash TEXT NOT NULL CHECK(length(payload_hash)=64),
  canonical_payload TEXT NOT NULL,
  actor TEXT NOT NULL,
  principal_kind TEXT NOT NULL CHECK(principal_kind IN ('user','service')),
  principal_id TEXT NOT NULL,
  previous_hash TEXT,
  event_hash TEXT NOT NULL UNIQUE CHECK(length(event_hash)=64),
  created_at TEXT NOT NULL
);
CREATE TABLE rm_intercompany_disposition_journal_links (
  id INTEGER PRIMARY KEY,
  disposition_id TEXT NOT NULL REFERENCES rm_intercompany_dispositions(disposition_id),
  side TEXT NOT NULL CHECK(side IN ('left','right')),
  company_slug TEXT NOT NULL,
  journal_entry_id INTEGER NOT NULL,
  journal_entry_no TEXT NOT NULL,
  journal_entry_hash TEXT NOT NULL CHECK(length(journal_entry_hash)=64),
  ledger_head_hash TEXT,
  linked_at TEXT NOT NULL,
  actor TEXT NOT NULL,
  principal_kind TEXT NOT NULL CHECK(principal_kind IN ('user','service')),
  principal_id TEXT NOT NULL,
  UNIQUE(disposition_id,side),
  UNIQUE(company_slug,journal_entry_id)
);
CREATE INDEX rm_intercompany_disposition_events_lookup ON rm_intercompany_disposition_events(disposition_id,id);
CREATE TRIGGER rm_intercompany_dispositions_no_update BEFORE UPDATE ON rm_intercompany_dispositions BEGIN SELECT RAISE(ABORT, 'intercompany dispositions are immutable'); END;
CREATE TRIGGER rm_intercompany_dispositions_no_delete BEFORE DELETE ON rm_intercompany_dispositions BEGIN SELECT RAISE(ABORT, 'intercompany dispositions are append-only'); END;
CREATE TRIGGER rm_intercompany_disposition_events_no_update BEFORE UPDATE ON rm_intercompany_disposition_events BEGIN SELECT RAISE(ABORT, 'intercompany disposition events are append-only'); END;
CREATE TRIGGER rm_intercompany_disposition_events_no_delete BEFORE DELETE ON rm_intercompany_disposition_events BEGIN SELECT RAISE(ABORT, 'intercompany disposition events are append-only'); END;
CREATE TRIGGER rm_intercompany_disposition_journal_links_no_update BEFORE UPDATE ON rm_intercompany_disposition_journal_links BEGIN SELECT RAISE(ABORT, 'intercompany journal links are append-only'); END;
CREATE TRIGGER rm_intercompany_disposition_journal_links_no_delete BEFORE DELETE ON rm_intercompany_disposition_journal_links BEGIN SELECT RAISE(ABORT, 'intercompany journal links are append-only'); END;
